package httpapi

import (
	"bytes"
	"embed"
	"io/fs"
	"net/http"
	"path"
	"strings"
	"tasker/backend/internal/httpapi/response"
	"time"
)

// webAssets is generated by `npm --prefix frontend run build` before Go is
// compiled. The all: prefix keeps the committed webui placeholder embeddable
// before the first frontend build.
//
//go:embed all:webui
var webAssets embed.FS

func newSPAHandler() http.Handler {
	assets, err := fs.Sub(webAssets, "webui/dist")
	if err != nil {
		return http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
			http.Error(w, "embedded frontend is unavailable; run make build", http.StatusInternalServerError)
		})
	}
	fileServer := http.FileServer(http.FS(assets))

	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet && r.Method != http.MethodHead {
			http.NotFound(w, r)
			return
		}
		// Preserve API 404s instead of returning the Vue entry point.
		if r.URL.Path == "/v1" || strings.HasPrefix(r.URL.Path, "/v1/") || r.URL.Path == "/api" || strings.HasPrefix(r.URL.Path, "/api/") {
			response.ProblemJSON(w, r, 404, "not_found", "API endpoint not found: "+r.URL.Path, nil)
			return
		}

		assetPath := strings.TrimPrefix(path.Clean(r.URL.Path), "/")
		if assetPath != "" {
			if info, err := fs.Stat(assets, assetPath); err == nil && !info.IsDir() {
				fileServer.ServeHTTP(w, r)
				return
			}
		}

		index, err := fs.ReadFile(assets, "index.html")
		if err != nil {
			http.Error(w, "embedded frontend is unavailable; run make build", http.StatusInternalServerError)
			return
		}
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		http.ServeContent(w, r, "index.html", time.Time{}, bytes.NewReader(index))
	})
}
